import { useRouteError } from 'react-router-dom';
import MainNavigation from '../components/MainNavigation';

import PageContent from '../components/PageContent';

function ErrorPage() {
  const error = useRouteError();

  let title = 'An error occurred!';
  let message = 'Something went wrong!';

  // Handle Response errors (thrown from loaders)
  if (error.status) {
    if (error.status === 404) {
      title = 'Not found!';
      // Try to get message from error.data, or parse it if it's a Response
      if (error.data) {
        message = typeof error.data === 'string' 
          ? (() => {
              try {
                const parsed = JSON.parse(error.data);
                return parsed.message || 'Could not find resource or page.';
              } catch {
                return error.data;
              }
            })()
          : error.data.message || 'Could not find resource or page.';
      } else {
        message = 'Could not find resource or page.';
      }
    } else if (error.status === 500) {
      if (error.data) {
        message = typeof error.data === 'string' 
          ? (() => {
              try {
                const parsed = JSON.parse(error.data);
                return parsed.message || 'Something went wrong!';
              } catch {
                return error.data;
              }
            })()
          : error.data.message || 'Something went wrong!';
      } else {
        message = 'Something went wrong!';
      }
    } else {
      if (error.data) {
        message = typeof error.data === 'string' 
          ? (() => {
              try {
                const parsed = JSON.parse(error.data);
                return parsed.message || error.message || 'Something went wrong!';
              } catch {
                return error.data;
              }
            })()
          : error.data.message || error.message || 'Something went wrong!';
      } else {
        message = error.message || 'Something went wrong!';
      }
    }
  } else {
    // Handle other types of errors (e.g., navigation errors, network errors)
    message = error.message || 'Something went wrong!';
  }

  return (
    <>
      <MainNavigation />
      <PageContent title={title}>
        <p>{message}</p>
      </PageContent>
    </>
  );
}

export default ErrorPage;
